1	/**
2	 * The era semantics of `ControlValueAccessor.setDisabledState`, restored through
3	 * the vendor's own switch.
4	 *
5	 * Angular's reactive-forms `setUpControl` used to call a value accessor's
6	 * `setDisabledState` only when the control it was attaching was already
7	 * disabled. An accessor attached to an *enabled* control never saw the method
8	 * run. Angular calls that a bug in its own source — "The legacy behavior only
9	 * calls the CVA's `setDisabledState` if the control is disabled. If the
10	 * `callSetDisabledState` option is set to `always`, then this bug is fixed and
11	 * the method is always called." — and from Angular 15 the fix is the default:
12	 * `setUpControl` calls `setDisabledState(control.disabled)` on every attach.
13	 *
14	 * For an accessor whose `setDisabledState` only toggles a flag, the fix is
15	 * invisible: `this.disabled = false` where the field was already false. For an
16	 * accessor whose `setDisabledState` does something — rebuilds a `FormGroup`,
17	 * re-reads a value, touches a subscription — the fix runs application code that
18	 * has never run before, at attach time, on every control. That is a behavioural
19	 * change a build cannot see, and it is not the application's mistake to fix: the
20	 * application's bytes did not change, the framework's attach semantics did.
21	 *
22	 * Angular ships the switch for exactly this migration. `CALL_SET_DISABLED_STATE`
23	 * provided as `'whenDisabledForLegacyCode'` — equivalently
24	 * `ReactiveFormsModule.withConfig({callSetDisabledState:
25	 * 'whenDisabledForLegacyCode'})` — restores the era guard byte for byte at the
26	 * seam that changed. So this capability provides it, and only where the
27	 * application's own bytes say the seam matters:
28	 *
29	 * - **Only when a custom accessor exists.** The accessors are read out of the
30	 *   `implements` clauses that resolve to `@angular/forms`' own
31	 *   `ControlValueAccessor`, not out of a name that happens to be spelled that
32	 *   way.
33	 * - **Only when one of them does more than toggle a flag.** The body of
34	 *   `setDisabledState` is classified statement by statement: writing a boolean
35	 *   field, or plumbing the `disabled` attribute/property onto an element, is a
36	 *   toggle; anything else is an effect, and it is the effects that make the new
37	 *   attach-time call observable. An application whose accessors only toggle gets
38	 *   nothing provided, because a provider nobody needs is a claim about the
39	 *   application its own source contradicts.
40	 * - **Only on a line that has the switch.** `callSetDisabledState` arrived in
41	 *   Angular 15. Below that line the era guard is still the framework's own
42	 *   behaviour and there is nothing to restore; configuring an option that line
43	 *   does not publish would not compile.
44	 *
45	 * The delivery seam is the root module's own `imports` list: every
46	 * `@angular/forms` module it names is configured through the `withConfig`
47	 * factory the package publishes. A bare root provider of the token would be the
48	 * narrower edit, but on Angular 16.2 `CALL_SET_DISABLED_STATE` is declared in
49	 * the package's typings and absent from its export surface — measured against
50	 * the installed closure, where a provider naming it fails to compile — so the
51	 * factory is what is actually available. Either way it is configuration rather
52	 * than a rewrite, and no application logic is touched, which is what keeps "the
53	 * migration changed no application behaviour" an honest sentence rather than a
54	 * repaired one.
55	 */
56	
57	import { compareStrings, majorOf, type AngularTargetCell } from './angular-target-cell.ts';
58	import { NG_MODULE_DECORATOR, NG_MODULE_PACKAGE } from './entry-components-removal.ts';
59	import {
60		applySourceEdits,
61		denotesExport,
62		forEachNode,
63		lineOf,
64		parseModule,
65		plainProperties,
66		readModuleImports,
67		type AstNode,
68		type SemanticModule,
69		type SourceEdit,
70	} from './semantic-module.ts';
71	
72	const CAPABILITY = 'Forms legacy disabled-state compatibility';
73	
74	/** The package that publishes the accessor contract, the token and the module. */
75	export const FORMS_PACKAGE = '@angular/forms';
76	
77	/** The interface a custom value accessor implements. */
78	export const CONTROL_VALUE_ACCESSOR_TYPE = 'ControlValueAccessor';
79	
80	/** The method whose call site Angular 15 changed. */
81	export const SET_DISABLED_STATE_METHOD = 'setDisabledState';
82	
83	/**
84	 * The injection token that selects the call-site behaviour.
85	 *
86	 * It is named here because it is what the configuration provides and what a
87	 * reader of the emitted bundle will find, but it is not what this capability
88	 * writes: on Angular 16.2 the token is declared in `@angular/forms`' typings
89	 * and is *not* on its published export surface, so a root provider naming it
90	 * does not compile. That was measured against the installed closure rather than
91	 * assumed, and the delivery seam below is the one the package actually
92	 * publishes for it.
93	 */
94	export const CALL_SET_DISABLED_STATE_TOKEN = 'CALL_SET_DISABLED_STATE';
95	
96	/** The published option that provides {@link CALL_SET_DISABLED_STATE_TOKEN}. */
97	export const CALL_SET_DISABLED_STATE_OPTION = 'callSetDisabledState';
98	
99	/** The static factory each forms module publishes for that option. */
100	export const WITH_CONFIG_FACTORY = 'withConfig';
101	
102	/** The value that restores the pre-15 guard. */
103	export const LEGACY_CALL_SET_DISABLED_STATE = 'whenDisabledForLegacyCode';
104	
105	/** The first Angular line that publishes the option and defaults to `always`. */
106	export const CALL_SET_DISABLED_STATE_ANGULAR_MAJOR = 15;
107	
108	/**
109	 * The modules that publish {@link WITH_CONFIG_FACTORY} for this option. Each
110	 * ships its own copy of the token provider for the directives it declares, so
111	 * an application importing both is configured on both: which of the two binds a
112	 * given accessor is the template's business, not this capability's.
113	 */
114	export const CONFIGURABLE_FORMS_MODULES: readonly string[] = Object.freeze([
115		'FormsModule',
116		'ReactiveFormsModule',
117	]);
118	
119	/**
120	 * The names an element's disabled state is plumbed through. A call naming one of
121	 * these with the `disabled` attribute is the accessor doing exactly what the
122	 * method is for, in the one shape that does not go through a field.
123	 */
124	export const DISABLED_PLUMBING_METHODS: readonly string[] = Object.freeze([
125		'setAttribute',
126		'removeAttribute',
127		'setProperty',
128		'setDisabledState',
129	]);
130	
131	/** One statement of a `setDisabledState` body that is not a disabled toggle. */
132	export type SetDisabledStateEffect = Readonly<{
133		/** The 1-based line the statement opens on. */
134		line: number;
135		/** The statement as the application writes it, whitespace collapsed. */
136		statement: string;
137		/** Why reading it as a toggle was refused. */
138		why: string;
139	}>;
140	
141	/** One custom value accessor, as its own source describes it. */
142	export type ControlValueAccessorReading = Readonly<{
143		/** The module the class is declared in. */
144		path: string;
145		/** The 1-based line the class opens on. */
146		line: number;
147		/** The class name, or null for an anonymous class expression. */
148		className: string | null;
149		/** Whether the class declares `setDisabledState` at all. */
150		declaresSetDisabledState: boolean;
151		/** Every statement of that method that is not a disabled toggle. */
152		effects: readonly SetDisabledStateEffect[];
153		/** Whether this accessor is one the era guard was hiding. */
154		legacy: boolean;
155	}>;
156	
157	/** The configuration edit written into the root module. */
158	export type LegacyCallSetDisabledStateChange = Readonly<{
159		kind: 'forms-legacy-call-set-disabled-state';
160		/** The module the configuration was written into. */
161		path: string;
162		/** The 1-based line of the `@NgModule` literal it was written into. */
163		line: number;
164		/** The token the configuration provides. */
165		token: typeof CALL_SET_DISABLED_STATE_TOKEN;
166		/** The published option written. */
167		option: typeof CALL_SET_DISABLED_STATE_OPTION;
168		/** The value provided. */
169		value: typeof LEGACY_CALL_SET_DISABLED_STATE;
170		/** The forms modules configured, in the order the literal names them. */
171		configuredModules: readonly string[];
172	}>;
173	
174	export type LegacyCallSetDisabledStateDeclaration = Readonly<{
175		/** Whether the provider was declared. */
176		declared: boolean;
177		/** The root module's source, rewritten only when something changed. */
178		rootModule: Readonly<{ path: string; source: string }> | null;
179		/** The provider written, or null when none was. */
180		change: LegacyCallSetDisabledStateChange | null;
181		/** Every custom accessor read, refused or not. */
182		accessors: readonly ControlValueAccessorReading[];
183		/** What providing this changes about the application, stated. */
184		declaredDifferences: readonly string[];
185		/** Everything refused, by name and with its reason. */
186		unhandled: readonly string[];
187	}>;
188	
189	/** One module handed to this capability. */
190	export type AngularModuleSource = Readonly<{ path: string; source: string }>;
191	
192	function collapse(text: string): string {
193		return text.replaceAll(/\s+/gu, ' ').trim();
194	}
195	
196	/** Whether a node is `this.<name>` written plainly. */
197	function thisMember(node: AstNode): string | null {
198		if (node.type !== 'MemberExpression' || node.computed || node.optional) return null;
199		if (node.object.type !== 'ThisExpression') return null;
200		return node.property.type === 'Identifier' ? node.property.name : null;
201	}
202	
203	/** The deepest non-computed property name of a member chain, or null. */
204	function trailingProperty(node: AstNode): string | null {
205		if (node.type !== 'MemberExpression' || node.computed) return null;
206		return node.property.type === 'Identifier' ? node.property.name : null;
207	}
208	
209	/**
210	 * Whether an expression is a boolean reading of the method's own parameter: the
211	 * parameter itself, a negation of it, or a boolean literal. Anything richer is
212	 * an effect, because a capability that guesses at what a call returns is
213	 * guessing at what the application does.
214	 */
215	function isBooleanOf(node: AstNode, parameter: string | null): boolean {
216		if (node.type === 'Identifier') return parameter !== null && node.name === parameter;
217		if (node.type === 'Literal') return typeof node.value === 'boolean';
218		if (node.type === 'UnaryExpression' && node.operator === '!')
219			return isBooleanOf(node.argument, parameter);
220		return false;
221	}
222	
223	/**
224	 * Whether a call is the accessor plumbing the `disabled` attribute onto an
225	 * element. `renderer.setProperty(el, 'disabled', isDisabled)` and its siblings
226	 * are the framework-blessed way to write the method's only real job, and they
227	 * are indistinguishable from a toggle in every way that matters here: nothing
228	 * the application owns changes shape.
229	 */
230	function isDisabledPlumbing(node: AstNode): boolean {
231		if (node.type !== 'CallExpression') return false;
232		const method = trailingProperty(node.callee);
233		if (method === null || !DISABLED_PLUMBING_METHODS.includes(method)) return false;
234		return node.arguments.some(
235			(argument) => argument.type === 'Literal' && argument.value === 'disabled',
236		);
237	}
238	
239	/**
240	 * Classify one statement of a `setDisabledState` body.
241	 *
242	 * Returns null when the statement is a disabled toggle, and the reason it is not
243	 * otherwise. The classification is deliberately narrow: everything this does not
244	 * recognise is an effect, so an accessor is never quietly read as harmless.
245	 */
246	function effectOf(source: string, statement: AstNode, parameter: string | null): string | null {
247		if (statement.type === 'EmptyStatement') return null;
248		if (statement.type !== 'ExpressionStatement')
249			return `it is a ${statement.type}, not an assignment or a call this capability can read`;
250		const expression = statement.expression;
251		if (expression.type === 'CallExpression')
252			return isDisabledPlumbing(expression)
253				? null
254				: 'it calls something other than a `disabled` attribute or property write, so the ' +
255						'call runs application code at attach time';
256		if (expression.type !== 'AssignmentExpression' || expression.operator !== '=')
257			return `it is a ${expression.type}, not a plain assignment or a call this capability can read`;
258		const field = thisMember(expression.left);
259		const property = trailingProperty(expression.left);
260		if (field === null && property !== 'disabled')
261			return 'it assigns to something other than a field of this instance or a `disabled` ' +
262				'property of an element';
263		if (!isBooleanOf(expression.right, parameter))
264			return field === null
265				? 'it assigns a value this capability cannot read as a boolean to a `disabled` property'
266				: `it assigns something other than the disabled flag to \`this.${field}\`, so attaching ` +
267						'a control now rebuilds application state that used to survive the attach';
268		return null;
269	}
270	
271	/** The parameter name of a method, when it takes exactly one plain identifier. */
272	function soleParameterName(value: AstNode): string | null {
273		if (value.type !== 'FunctionExpression' && value.type !== 'ArrowFunctionExpression') return null;
274		const first = value.params[0];
275		if (first === undefined) return null;
276		return first.type === 'Identifier' ? first.name : null;
277	}
278	
279	type ClassNode = Extract<AstNode, { type: 'ClassDeclaration' | 'ClassExpression' }>;
280	type MethodNode = Extract<AstNode, { type: 'MethodDefinition' }>;
281	
282	/** The class a node sits inside, or null. */
283	function enclosingClass(module: SemanticModule, node: AstNode): ClassNode | null {
284		let current: AstNode | null = node;
285		while (current !== null) {
286			if (current.type === 'ClassDeclaration' || current.type === 'ClassExpression') return current;
287			current = module.parentOf(current);
288		}
289		return null;
290	}
291	
292	/**
293	 * Read every custom `ControlValueAccessor` one module declares, and classify
294	 * what each one's `setDisabledState` does.
295	 *
296	 * The accessors are found through the resolved binding of the `implements`
297	 * clause: a class implementing some other interface spelled the same way is not
298	 * one of Angular's, and a class implementing Angular's under an alias is.
299	 */
300	export function readControlValueAccessors(
301		path: string,
302		source: string,
303	): readonly ControlValueAccessorReading[] {
304		const module = parseModule(CAPABILITY, path, source);
305		const forms = readModuleImports(module, FORMS_PACKAGE);
306		if (!forms.present) return Object.freeze([]);
307		const readings: ControlValueAccessorReading[] = [];
308		const seen = new Set<AstNode>();
309		forEachNode(module.ast, (node) => {
310			if (node.type !== 'TSClassImplements') return;
311			if (!denotesExport(module, node.expression, forms, CONTROL_VALUE_ACCESSOR_TYPE)) return;
312			const declaration = enclosingClass(module, node);
313			if (declaration === null || seen.has(declaration)) return;
314			seen.add(declaration);
315			const className = declaration.id?.type === 'Identifier' ? declaration.id.name : null;
316			const method = declaration.body.body.find(
317				(member) =>
318					member.type === 'MethodDefinition' &&
319					!member.computed &&
320					member.key.type === 'Identifier' &&
321					member.key.name === SET_DISABLED_STATE_METHOD,
322			) as MethodNode | undefined;
323			const effects: SetDisabledStateEffect[] = [];
324			if (method !== undefined) {
325				const parameter = soleParameterName(method.value);
326				const body = method.value.body;
327				if (body === null || body === undefined || body.type !== 'BlockStatement')
328					effects.push(
329						Object.freeze({
330							line: lineOf(source, method.start),
331							statement: `${SET_DISABLED_STATE_METHOD}(…)`,
332							why: 'the method has no readable statement body, so what it does at attach time cannot be read',
333						}),
334					);
335				else
336					for (const statement of body.body) {
337						const why = effectOf(source, statement, parameter);
338						if (why === null) continue;
339						effects.push(
340							Object.freeze({
341								line: lineOf(source, statement.start),
342								statement: collapse(source.slice(statement.start, statement.end)),
343								why,
344							}),
345						);
346					}
347			}
348			readings.push(
349				Object.freeze({
350					path,
351					line: lineOf(source, declaration.start),
352					className,
353					declaresSetDisabledState: method !== undefined,
354					effects: Object.freeze(effects),
355					legacy: effects.length > 0,
356				}),
357			);
358		});
359		return Object.freeze(readings);
360	}
361	
362	/** The `@NgModule` literal that bootstraps the application, in one module. */
363	function rootModuleLiteral(
364		module: SemanticModule,
365		source: string,
366	): Readonly<{ literal: AstNode; line: number }> | null {
367		const core = readModuleImports(module, NG_MODULE_PACKAGE);
368		if (!core.present) return null;
369		let found: Readonly<{ literal: AstNode; line: number }> | null = null;
370		forEachNode(module.ast, (node) => {
371			if (found !== null || node.type !== 'Decorator') return;
372			const call = node.expression;
373			if (call.type !== 'CallExpression') return;
374			if (!denotesExport(module, call.callee, core, NG_MODULE_DECORATOR)) return;
375			const literal = call.arguments[0];
376			if (literal === undefined || literal.type !== 'ObjectExpression') return;
377			const properties = plainProperties(literal);
378			if (properties === null) return;
379			if (!properties.some((property) => property.name === 'bootstrap')) return;
380			found = Object.freeze({ literal, line: lineOf(source, node.start) });
381		});
382		return found;
383	}
384	
385	function refusal(reasons: readonly string[], accessors: readonly ControlValueAccessorReading[]) {
386		return Object.freeze({
387			declared: false,
388			rootModule: null,
389			change: null,
390			accessors,
391			declaredDifferences: Object.freeze([]),
392			unhandled: Object.freeze([...reasons]),
393		}) satisfies LegacyCallSetDisabledStateDeclaration;
394	}
395	
396	/**
397	 * Provide the era call-site behaviour for an application that crosses the
398	 * Angular 15 boundary carrying a value accessor the era guard was hiding.
399	 *
400	 * Every module handed in is read for accessors; exactly one of them is expected
401	 * to carry the bootstrapping `@NgModule`, and the provider is written into that
402	 * literal's `providers` array. A workspace with no bootstrapping module, or more
403	 * than one, is refused by name rather than picked between.
404	 */
405	export function declareLegacyCallSetDisabledState(input: {
406		modules: readonly AngularModuleSource[];
407		cell: AngularTargetCell;
408	}): LegacyCallSetDisabledStateDeclaration {
409		const accessors: ControlValueAccessorReading[] = [];
410		for (const module of input.modules)
411			accessors.push(...readControlValueAccessors(module.path, module.source));
412		const frozen = Object.freeze([...accessors]);
413		const legacy = frozen.filter((reading) => reading.legacy);
414		if (legacy.length === 0)
415			return refusal(
416				[
417					`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: of the ${String(frozen.length)} ` +
418						`custom ${CONTROL_VALUE_ACCESSOR_TYPE} implementations read across ` +
419						`${String(input.modules.length)} modules, none declares a ` +
420						`\`${SET_DISABLED_STATE_METHOD}\` that does anything but toggle its disabled state, ` +
421						'so Angular 15\'s attach-time call is unobservable here and restoring the era guard ' +
422						'would be a provider answering a question this application does not ask',
423				],
424				frozen,
425			);
426		const major = majorOf(input.cell.angularLine);
427		if (major === null || major < CALL_SET_DISABLED_STATE_ANGULAR_MAJOR)
428			return refusal(
429				[
430					`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: the declared cell is on Angular ` +
431						`${input.cell.angularLine}, which does not publish the token and whose ` +
432						'`setUpControl` already applies the legacy guard, so there is nothing here to restore',
433				],
434				frozen,
435			);
436		const roots: Array<{
437			module: AngularModuleSource;
438			parsed: SemanticModule;
439			literal: AstNode;
440			line: number;
441		}> = [];
442		for (const module of input.modules) {
443			const parsed = parseModule(CAPABILITY, module.path, module.source);
444			const root = rootModuleLiteral(parsed, module.source);
445			if (root === null) continue;
446			roots.push({ module, parsed, literal: root.literal, line: root.line });
447		}
448		if (roots.length !== 1) {
449			const names = roots.map((entry) => entry.module.path).sort(compareStrings);
450			return refusal(
451				[
452					`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: ` +
453						(roots.length === 0
454							? `none of the ${String(input.modules.length)} modules read carries an ` +
455								`@${NG_MODULE_DECORATOR} literal with a \`bootstrap\` property, so this ` +
456								'capability cannot say which providers are the application\'s root providers'
457							: `${String(roots.length)} modules carry a bootstrapping @${NG_MODULE_DECORATOR} ` +
458								`literal (${names.join(', ')}), and choosing between them is the ` +
459								'application\'s decision rather than this capability\'s'),
460				],
461				frozen,
462			);
463		}
464		const root = roots[0]!;
465		const { module, parsed, literal, line } = root;
466		const source = module.source;
467		const properties = plainProperties(literal)!;
468		const imports = properties.find((property) => property.name === 'imports');
469		if (imports === undefined || imports.value.type !== 'ArrayExpression')
470			return refusal(
471				[
472					`${CALL_SET_DISABLED_STATE_OPTION} was not configured: the bootstrapping ` +
473						`@${NG_MODULE_DECORATOR} literal in ${module.path} carries ` +
474						(imports === undefined
475							? 'no `imports` property'
476							: 'an `imports` value that is not a plain array') +
477						`, so there is no ${FORMS_PACKAGE} module in it this capability can read as the one ` +
478						'whose directives attach the accessors',
479				],
480				frozen,
481			);
482		const forms = readModuleImports(parsed, FORMS_PACKAGE);
483		const edits: SourceEdit[] = [];
484		const configured: string[] = [];
485		const quote = source.slice(literal.start, literal.end).includes('"') ? '"' : "'";
486		for (const element of imports.value.elements as readonly (AstNode | null)[]) {
487			if (element === null) continue;
488			const name = CONFIGURABLE_FORMS_MODULES.find((candidate) =>
489				denotesExport(parsed, element, forms, candidate),
490			);
491			if (name === undefined) continue;
492			configured.push(name);
493			edits.push({
494				start: element.end,
495				end: element.end,
496				text:
497					`.${WITH_CONFIG_FACTORY}({${CALL_SET_DISABLED_STATE_OPTION}: ` +
498					`${quote}${LEGACY_CALL_SET_DISABLED_STATE}${quote}})`,
499			});
500		}
501		if (configured.length === 0)
502			return refusal(
503				[
504					`${CALL_SET_DISABLED_STATE_OPTION} was not configured: the bootstrapping ` +
505						`@${NG_MODULE_DECORATOR} literal in ${module.path} names none of ` +
506						`${CONFIGURABLE_FORMS_MODULES.join(' or ')} as a plain \`${FORMS_PACKAGE}\` binding in ` +
507						`its \`imports\`, so there is nothing here publishing \`${WITH_CONFIG_FACTORY}\` for ` +
508						`this option, and a root provider of \`${CALL_SET_DISABLED_STATE_TOKEN}\` is not ` +
509						`available either: the token is declared in \`${FORMS_PACKAGE}\`'s typings and is ` +
510						'not on its published export surface',
511				],
512				frozen,
513			);
514		const rewritten = applySourceEdits(source, edits);
515		const names = legacy
516			.map((reading) => `${reading.path}:${reading.className ?? '<anonymous>'}`)
517			.sort(compareStrings);
518		return Object.freeze({
519			declared: true,
520			rootModule: Object.freeze({ path: module.path, source: rewritten }),
521			change: Object.freeze({
522				kind: 'forms-legacy-call-set-disabled-state' as const,
523				path: module.path,
524				line,
525				token: CALL_SET_DISABLED_STATE_TOKEN,
526				option: CALL_SET_DISABLED_STATE_OPTION,
527				value: LEGACY_CALL_SET_DISABLED_STATE,
528				configuredModules: Object.freeze([...configured]),
529			}),
530			accessors: frozen,
531			declaredDifferences: Object.freeze([
532				`Angular ${input.cell.angularLine} calls \`${SET_DISABLED_STATE_METHOD}\` on every ` +
533					`${CONTROL_VALUE_ACCESSOR_TYPE} as it attaches a control; with ` +
534					`${configured.join(' and ')} configured ` +
535					`\`${CALL_SET_DISABLED_STATE_OPTION}: ${LEGACY_CALL_SET_DISABLED_STATE}\` — which is how ` +
536					`${FORMS_PACKAGE} publishes the \`${CALL_SET_DISABLED_STATE_TOKEN}\` provider — it calls ` +
537					'it only for a control that is already disabled, which is what Angular did before 15. ' +
538					`${String(legacy.length)} of this application's ${String(frozen.length)} custom accessors ` +
539					`(${names.join(', ')}) do more in that method than toggle a flag, so the difference is ` +
540					'observable here. Angular names the pre-15 behaviour a bug in its own source and ships ' +
541					'this switch to opt back into it for migrated code; no application logic was rewritten, ' +
542					'and the accessors keep whatever defects they already had.',
543			]),
544			unhandled: Object.freeze([]),
545		});
546	}
