77	export type TextInputDirectiveReading = Readonly<{
78		directive: string;
79		/** The element part of its selector, e.g. `input` of `input[matChipInputFor]`. */
80		element: string;
81		/** The template-facing name of the input that names the container. */
82		hostBinding: string;
