102	 * on the strength of this record alone: every one of its three names is verified
103	 * against the installed declarations before a single tag is touched.
104	 */
105	export type DocumentedElementSplit = Readonly<{
106		package: string;
107		replaced: string;
108		since: string;
109		/** The successor for a list hosting the library's text-input directive. */
110		inputBearing: string;
111		/** The successor for a list carrying selection bindings. */
112		selection: string;
113		/** The successor for a list carrying neither — the one the other two extend. */
114		general: string;
