117	/** The splits this adapter has been told about. */
118	export const DOCUMENTED_ELEMENT_SPLITS: readonly DocumentedElementSplit[] = Object.freeze([
119		Object.freeze({
120			package: '@angular/material',
121			replaced: 'mat-chip-list',
122			since: '@angular/material 15 (MDC chips)',
123			inputBearing: 'MatChipGrid',
124			selection: 'MatChipListbox',
125			general: 'MatChipSet',
126		}),
