129	export type SplitElementShape = 'input-bearing' | 'selection' | 'general';
130	
131	export type SplitElementChange = Readonly<{
132		kind: 'split-element-successor';
133		line: number;
134		from: string;
135		to: string;
136		shape: SplitElementShape;
137		component: string;
138		/** The child renames the container's content query required, if any. */
139		children: readonly string[];
140	}>;
