150	/**
151	 * Attributes every element carries whatever component matches it. A binding
152	 * outside this set and outside the successor's own surface is a binding this
153	 * capability cannot account for, and it refuses rather than drop it.
154	 */
155	const UNIVERSAL_ATTRIBUTES: readonly string[] = Object.freeze([
156		'class',
157		'style',
158		'id',
159		'title',
160		'hidden',
161		'tabindex',
162	]);
163	
164	const UNIVERSAL_PREFIXES: readonly string[] = Object.freeze([
165		'data-',
166		'aria-',
167		'attr.',
168		'class.',
169		'style.',
170	]);
