177	/** Every element node of a parsed template, in source order, outermost first. */
178	function elementsOf(nodes: readonly TmplAstNode[], found: TmplAstElement[]): void {
179		for (const node of nodes) {
180			if (node instanceof TmplAstElement) found.push(node);
181			const children: unknown = (node as { children?: unknown }).children;
182			if (Array.isArray(children)) elementsOf(children as readonly TmplAstNode[], found);
183		}
184	}
185	
186	/** The elements beneath `root`, not including it. */
187	function descendantsOf(root: TmplAstElement): readonly TmplAstElement[] {
188		const found: TmplAstElement[] = [];
189		elementsOf(root.children, found);
190		return Object.freeze(found);
191	}
192	
193	/** Every template-facing binding name written on an element. */
194	function bindingNamesOf(element: TmplAstElement): readonly string[] {
195		return Object.freeze([
196			...element.attributes.map((attribute) => attribute.name),
197			...element.inputs.map((input) => input.name),
198			...element.outputs.map((output) => output.name),
199		]);
200	}
201	
202	function componentNamed(
203		reading: ElementSplitReading,
204		name: string,
205	): ComponentSurfaceReading | null {
206		return reading.components.find((entry) => entry.component === name) ?? null;
207	}
208	
209	/** A component's own inputs and outputs, plus every one it inherits. */
210	function surfaceOf(reading: ElementSplitReading, name: string): readonly string[] {
211		const component = componentNamed(reading, name);
212		if (component === null) return Object.freeze([]);
213		const names = new Set<string>([...component.inputs, ...component.outputs]);
214		for (const base of component.extendsChain) {
215			const declared = componentNamed(reading, base);
216			if (declared === null) continue;
217			for (const entry of [...declared.inputs, ...declared.outputs]) names.add(entry);
218		}
219		return Object.freeze([...names].sort(compareStrings));
220	}
221	
222	/** The component whose element selectors include `element`, when exactly one does. */
223	function componentOfElement(
224		reading: ElementSplitReading,
225		element: string,
226	): ComponentSurfaceReading | null {
227		const matches = reading.components.filter((entry) => entry.elements.includes(element));
228		return matches.length === 1 ? (matches[0] as ComponentSurfaceReading) : null;
229	}
230	
231	/**
232	 * Whether the documented split describes the installed tree, and why not when it
233	 * does not.
234	 *
235	 * Five checks, each against a declaration rather than against the claim: the
236	 * replaced element really is gone; each named successor is declared and carries
237	 * exactly one element selector; the input-bearing one is the one the text-input
238	 * directive's host binding is typed to; the general one is a base of both others;
239	 * and the two specialisations are not bases of each other.
240	 */
241	export function checkElementSplit(
242		split: DocumentedElementSplit,
243		reading: ElementSplitReading,
244	): readonly string[] {
245		const refusals: string[] = [];
246		const at = `'${split.package}'@${reading.version}`;
247		if (!reading.complete) {
248			refusals.push(
249				`the reading of ${at} could not be completed, so it establishes neither which successors ` +
250					'are declared nor that the replaced element is gone',
251			);
252			return Object.freeze(refusals);
253		}
254		if (reading.replacedStillDeclared)
255			refusals.push(
256				`${at} still declares <${split.replaced}>, so the diagnostic does not describe this closure ` +
257					'and a rewrite would be a rewrite of working markup',
258			);
259		for (const name of [split.inputBearing, split.selection, split.general]) {
260			const component = componentNamed(reading, name);
261			if (component === null) {
262				refusals.push(`${at} declares no component named ${name}`);
263				continue;
264			}
265			if (component.elements.length !== 1)
266				refusals.push(
267					`${name} in ${at} matches ${String(component.elements.length)} element selectors ` +
268						`(${component.elements.join(', ')}), so which one succeeds <${split.replaced}> is not ` +
269						'established',
270				);
271		}
272		const textInput = reading.textInput;
273		if (textInput === null)
274			refusals.push(
275				`${at} declares no text-input directive, so the input-bearing shape cannot be told from ` +
276					'the others',
277			);
278		else if (textInput.hostComponent !== split.inputBearing)
279			refusals.push(
280				`${textInput.directive} in ${at} types its ${textInput.hostBinding} binding to ` +
281					`${textInput.hostComponent}, and the split claims the input-bearing successor is ` +
282					`${split.inputBearing}`,
283			);
284		const inputBearing = componentNamed(reading, split.inputBearing);
285		const selection = componentNamed(reading, split.selection);
286		if (inputBearing !== null && !inputBearing.extendsChain.includes(split.general))
287			refusals.push(
288				`${split.inputBearing} in ${at} does not extend ${split.general}, so ${split.general} is ` +
289					'not the unspecialised container the split claims it is',
290			);
291		if (selection !== null && !selection.extendsChain.includes(split.general))
292			refusals.push(
293				`${split.selection} in ${at} does not extend ${split.general}, so ${split.general} is not ` +
294					'the unspecialised container the split claims it is',
295			);
296		if (inputBearing !== null && inputBearing.extendsChain.includes(split.selection))
297			refusals.push(
298				`${split.inputBearing} in ${at} extends ${split.selection}, so the two shapes the split ` +
299					'distinguishes are not distinct successors',
300			);
301		if (selection !== null && selection.extendsChain.includes(split.inputBearing))
302			refusals.push(
303				`${split.selection} in ${at} extends ${split.inputBearing}, so the two shapes the split ` +
304					'distinguishes are not distinct successors',
305			);
306		return Object.freeze(refusals);
307	}
308	
309	type Resolution =
310		| Readonly<{ kind: 'resolved'; shape: SplitElementShape; component: string }>
311		| Readonly<{ kind: 'refused'; reason: string }>;
312	
313	/** Which of the documented shapes this call site's template facts match. */
314	function resolveShape(
315		source: string,
316		element: TmplAstElement,
317		split: DocumentedElementSplit,
318		reading: ElementSplitReading,
319	): Resolution {
320		const textInput = reading.textInput;
321		if (textInput === null) return { kind: 'refused', reason: 'no text-input directive was read' };
322		const references = element.references.map((reference) => reference.name);
323		let hostsTextInput = false;
324		let foreign: string | null = null;
325		for (const descendant of descendantsOf(element)) {
326			if (descendant.name !== textInput.element) continue;
327			const binding = descendant.inputs.find((input) => input.name === textInput.hostBinding);
328			if (binding === undefined) continue;
329			const span = binding.valueSpan;
330			const named =
331				span === undefined ? '' : source.slice(span.start.offset, span.end.offset).trim();
332			if (references.includes(named)) hostsTextInput = true;
333			else foreign = named === '' ? '(an expression)' : named;
334		}
335		if (foreign !== null)
336			return {
337				kind: 'refused',
338				reason:
339					`it contains a <${textInput.element}> whose ${textInput.hostBinding} names ${foreign}, ` +
340					'which is not a reference this element declares, so which container that input belongs ' +
341					'to is not established here',
342			};
343		const written = bindingNamesOf(element);
344		const selectionOnly = surfaceOf(reading, split.selection).filter(
345			(name) =>
346				!surfaceOf(reading, split.inputBearing).includes(name) &&
347				!surfaceOf(reading, split.general).includes(name),
348		);
349		const discriminating = written.filter((name) => selectionOnly.includes(name));
350		if (hostsTextInput && discriminating.length > 0)
351			return {
352				kind: 'refused',
353				reason:
354					`it hosts a ${textInput.hostBinding} and also carries ${discriminating.join(', ')}, ` +
355					`which only ${split.selection} declares — the facts match two documented shapes at once`,
356			};
357		if (hostsTextInput)
358			return { kind: 'resolved', shape: 'input-bearing', component: split.inputBearing };
359		if (discriminating.length > 0)
360			return { kind: 'resolved', shape: 'selection', component: split.selection };
361		return { kind: 'resolved', shape: 'general', component: split.general };
362	}
363	
364	/** The edit that rewrites an element's tag name, open and close. */
365	function retagEdits(source: string, element: TmplAstElement, to: string): readonly SourceEdit[] {
366		const edits: SourceEdit[] = [];
367		const open = element.startSourceSpan.start.offset + 1;
368		if (source.slice(open, open + element.name.length) !== element.name) return Object.freeze([]);
369		edits.push({ start: open, end: open + element.name.length, text: to });
370		const closing = element.endSourceSpan;
371		if (closing !== null && closing.start.offset !== element.startSourceSpan.start.offset) {
372			const close = closing.start.offset + 2;
373			if (source.slice(close, close + element.name.length) === element.name)
374				edits.push({ start: close, end: close + element.name.length, text: to });
375		}
376		return Object.freeze(edits);
377	}
378	
379	/**
380	 * Rewrite one template's occurrences of a split element onto the successors the
381	 * installed declarations and the template's own facts agree on.
382	 */
383	export function resolveSplitElementSuccessors(
384		path: string,
385		source: string,
386		split: DocumentedElementSplit,
387		reading: ElementSplitReading,
388	): SplitElementMigration {
389		const unchanged = (unhandled: readonly string[]): SplitElementMigration =>
390			Object.freeze({
391				path,
392				source,
393				changed: false,
394				changes: Object.freeze([]),
395				unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
396			});
397		if (split.package !== reading.package || split.replaced !== reading.replaced)
398			return unchanged([
399				`${path}: the reading is of ${reading.package} <${reading.replaced}> and the split ` +
400					`describes ${split.package} <${split.replaced}>`,
401			]);
402		const mismatches = checkElementSplit(split, reading);
403		if (mismatches.length > 0)
404			return unchanged(mismatches.map((reason) => `${path}: ${reason}, so nothing was rewritten`));
405		const parsed = parseTemplate(source, path, { preserveWhitespaces: true });
406		if (parsed.errors !== null && parsed.errors.length > 0)
407			throw new Error(
408				`${CAPABILITY}: ${path} does not parse, so it cannot be rewritten and it cannot be ` +
409					`honestly counted as unchanged. Diagnostics: ` +
410					parsed.errors.map((error) => error.toString()).join('; '),
411			);
412		const all: TmplAstElement[] = [];
413		elementsOf(parsed.nodes, all);
414		const edits: SourceEdit[] = [];
415		const changes: SplitElementChange[] = [];
416		const unhandled: string[] = [];
417		for (const element of all) {
418			if (element.name !== split.replaced) continue;
419			const line = lineOf(source, element.startSourceSpan.start.offset);
420			const at = `${path} line ${String(line)}`;
421			const resolution = resolveShape(source, element, split, reading);
422			if (resolution.kind === 'refused') {
423				unhandled.push(`${at}: <${split.replaced}> was left as it is because ${resolution.reason}`);
424				continue;
425			}
426			const successor = componentNamed(reading, resolution.component);
427			if (successor === null) continue;
428			const successorElement = successor.elements[0] as string;
429			const carried = surfaceOf(reading, resolution.component);
430			const unaccounted = bindingNamesOf(element).filter(
431				(name) => !isUniversal(name) && !carried.includes(name),
432			);
433			if (unaccounted.length > 0) {
434				unhandled.push(
435					`${at}: <${split.replaced}> carries ${unaccounted.join(', ')}, which ` +
436						`${resolution.component} does not declare, and the component this element used to ` +
437						'match is not in the installed tree to say whether those are its inputs or another ' +
438						"directive's",
439				);
440				continue;
441			}
442			const childName = successor.contentChildComponent;
443			if (childName === null) {
444				unhandled.push(
445					`${at}: ${resolution.component} declares no content query, so which child element it ` +
446						'accepts is not established',
447				);
448				continue;
449			}
450			const child = componentNamed(reading, childName);
451			if (child === null) {
452				unhandled.push(
453					`${at}: ${resolution.component} queries for ${childName}, which the reading does not ` +
454						'carry',
455				);
456				continue;
457			}
458			const childEdits: SourceEdit[] = [];
459			const childChanges: string[] = [];
460			let refusedChild: string | null = null;
461			for (const descendant of descendantsOf(element)) {
462				const written = componentOfElement(reading, descendant.name);
463				if (written === null) continue;
464				if (written.component === childName) continue;
465				if (written.contentChildComponent !== null) continue;
466				if (!child.extendsChain.includes(written.component)) {
467					refusedChild =
468						`<${descendant.name}> resolves to ${written.component}, which ${childName} does not ` +
469						`extend, so renaming it onto ${childName} would not be a rename`;
470					break;
471				}
472				const successors = child.elements.filter((entry) => entry.startsWith(descendant.name));
473				if (successors.length !== 1) {
474					refusedChild =
475						`<${descendant.name}> has ${String(successors.length)} candidate successors among ` +
476						`${childName}'s element selectors (${child.elements.join(', ')})`;
477					break;
478				}
479				const to = successors[0] as string;
480				childEdits.push(...retagEdits(source, descendant, to));
481				childChanges.push(`${descendant.name} → ${to}`);
482			}
483			if (refusedChild !== null) {
484				unhandled.push(
485					`${at}: <${split.replaced}> was left as it is because ${refusedChild}. Rewriting the ` +
486						'container without its children would move the failure rather than answer it.',
487				);
488				continue;
489			}
490			const containerEdits = retagEdits(source, element, successorElement);
491			if (containerEdits.length === 0) {
492				unhandled.push(
493					`${at}: the parsed open tag of <${split.replaced}> is not where the source writes it`,
494				);
495				continue;
496			}
497			edits.push(...containerEdits, ...childEdits);
498			changes.push({
499				kind: 'split-element-successor',
500				line,
501				from: split.replaced,
502				to: successorElement,
503				shape: resolution.shape,
504				component: resolution.component,
505				children: Object.freeze([...new Set(childChanges)].sort(compareStrings)),
506			});
507		}
508		const migrated = applySourceEdits(source, edits);
509		return Object.freeze({
510			path,
511			source: migrated,
512			changed: migrated !== source,
513			changes: Object.freeze(changes),
514			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
515		});
516	}
517	
518	/**
519	 * The `NG8001` lines of a build log, as the templates they name.
520	 *
521	 * Only the element and the file are taken. The capability re-reads the template
522	 * to find every occurrence, because a diagnostic is raised once per unknown
523	 * element name and a template may write it more than once.
524	 */
525	export function readUnknownElements(log: string): ReadonlyMap<string, readonly string[]> {
526		const found = new Map<string, Set<string>>();
527		for (const raw of log.split('\n')) {
528			const line = raw.trim();
529			const head = UNKNOWN_ELEMENT_HEAD.exec(line)?.groups;
530			const message = UNKNOWN_ELEMENT.exec(line)?.groups;
531			if (head === undefined || message === undefined) continue;
532			const file = head['file'] as string;
533			const element = message['element'] as string;
534			const list = found.get(file);
535			if (list === undefined) found.set(file, new Set([element]));
536			else list.add(element);
537		}
538		return new Map(
539			[...found].map(([file, list]) => [file, Object.freeze([...list].sort(compareStrings))]),
540		);
541	}
542	
543	/** The position and code the builder prints in front of an unknown-element message. */
544	const UNKNOWN_ELEMENT_HEAD = createRegExp(
545		maybe(exactly('Error:').and(oneOrMore(whitespace)))
546			.and(oneOrMore(charNotIn(' \t\n:')).as('file'))
547			.and(exactly(':'))
548			.and(oneOrMore(digit))
549			.and(exactly(':'))
550			.and(oneOrMore(digit))
551			.and(exactly(' - error NG8001: ')),
552	);
553	
554	/** The message body, which names the element the template compiler could not match. */
555	const UNKNOWN_ELEMENT = createRegExp(
556		exactly("'")
557			.and(oneOrMore(charNotIn("'")).as('element'))
558			.and(exactly("' is not a known element")),
559	);
560

